/* ==========================================================
   1. كود البحث (Search Box)
   ========================================================== */
(function() {
  'use strict';

  window.searchBlog = function() {
    const searchInput = document.getElementById('search-input');
    if (!searchInput) return false;
    const query = searchInput.value;
    if (query.trim()) {
      window.location.href = '/search?q=' + encodeURIComponent(query);
    }
    return false;
  };

  function initSearch() {
    const searchBox = document.getElementById('search-box');
    const searchToggle = document.getElementById('search-toggle');
    const searchClose = document.getElementById('search-close');

    if (searchToggle && searchBox && searchClose) {
      searchToggle.onclick = function() {
        searchBox.style.display = 'flex';
        setTimeout(() => searchBox.style.opacity = '1', 10);
      };

      searchClose.onclick = function() {
        searchBox.style.opacity = '0';
        setTimeout(() => searchBox.style.display = 'none', 400);
      };

      searchBox.onclick = function(e) {
        if (e.target === searchBox) searchClose.onclick();
      };
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initSearch);
  } else {
    initSearch();
  }
})();



/* ==========================================================
   2. كود الوضع الليلي (Dark Mode Toggle)
   ========================================================== */
(function() {
  'use strict';

  function initDarkMode() {
    const toggleBtn = document.getElementById('dark-mode-toggle');
    if (!toggleBtn) return;

    toggleBtn.addEventListener('click', function () {
      document.documentElement.classList.toggle('dark-mode');

      if (document.documentElement.classList.contains('dark-mode')) {
        localStorage.setItem('dark-mode', 'enabled');
      } else {
        localStorage.setItem('dark-mode', 'disabled');
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initDarkMode);
  } else {
    initDarkMode();
  }
})();
/* ==========================================================
   3. مقالات مميزة
   ========================================================== */

function w1_FeedUrl(label,maxResults){return"/feeds/posts/default/-/"+encodeURIComponent(label)+"?alt=json&max-results="+maxResults}
function w1_Thumbnail(content){let div=document.createElement("div");div.innerHTML=content;let img=div.querySelector("img");return img?img.getAttribute("src"):"https://via.placeholder.com/480x270.png?text=No+Image"}

function w1_PrintFeed(entries){
  let html="";
  for(let i=0;i<entries.length;i++){
    let entry=entries[i];
    let title=(entry.title?.$t||"").replace(/"/g,'&quot;');
    let url="#";
    if(entry.link){
      const alternateLink=entry.link.find(link=>link.rel==="alternate");
      if(alternateLink){url=alternateLink.href}
    }
    let content=entry.content?.$t||"";
    let img=entry.media$thumbnail?.url||w1_Thumbnail(content);
    img=img.replace(/\/s[0-9]+(-c)?/,"/s480");
    
    html+=`
      <div class="w1-custom-featured-item">
        <a href="${url}" class="w1-custom-featured-link" aria-label="${title}"></a>
        <div class="w1-custom-featured-image">
          <img data-src="${img}" src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 119 85'%3E%3C/svg%3E" alt="${title}" width="119" height="85">
        </div>
        <div class="w1-custom-featured-content">
          <h3 class="w1-custom-featured-title">${title}</h3>
        </div>
      </div>
    `;
  }
  return `<div class="w1-custom-featured-wrapper">${html}</div>`;
}

(function(){
  var w1Loaded = false;
  async function loadW1Feeds(){
    if(w1Loaded) return;
    w1Loaded = true;

    const section=document.querySelector('#widget1CustomFeaturedMulti');
    if(!section)return;
    const widgets=section.querySelectorAll('.widget');
    for(let widget of widgets){
      let container=widget.querySelector('.widget-content');
      if(!container)continue;
      let label=container.textContent?.trim();
      if(!label)continue;
      try{
        const response=await fetch(w1_FeedUrl(label,3));
        const data=await response.json();
        const entries=data.feed?.entry||[];
        if(entries.length>0){
          container.innerHTML=`<h2 class="w1-section-title">${label}</h2>${w1_PrintFeed(entries)}`;
        }else{
          container.innerHTML=`<h2 class="w1-section-title">${label}</h2><p style='text-align:center;'>لا توجد مقالات لعرضها في قسم "${label}".</p>`;
        }
      }catch(error){
        container.innerHTML=`<h2 class="w1-section-title">${label}</h2><p style='color:red;text-align:center;'>فشل تحميل المقالات</p>`;
      }
    }
    triggerLazyImages();
  }

  window.addEventListener('scroll', loadW1Feeds, {passive: true, once: true});
  window.addEventListener('touchstart', loadW1Feeds, {passive: true, once: true});
  window.addEventListener('mousemove', loadW1Feeds, {passive: true, once: true});
})();

/* ==========================================================
   4. مقالات مميزة
   ========================================================== */

function w2_Feedurl(label,maxResults){return "/feeds/posts/default/-/"+encodeURIComponent(label)+"?alt=json&max-results="+maxResults}
function w2_Thumbnail(content){let div=document.createElement("div");div.innerHTML=content;let img=div.querySelector("img");return img ? img.getAttribute("src"):"https://via.placeholder.com/480x270.png?text=No+Image"}

function w2_PrintFancyFeed(entries,sectionLabel){
  let mainHTML="";
  let listHTML="";
  let limitedEntries=entries.slice(0,4);
  for (let i=0;i < limitedEntries.length;i++){
    let entry=limitedEntries[i];
    let title=(entry.title?.$t||"").replace(/"/g,'&quot;');
    let url="#";
    if (entry.link){
      const altLink=entry.link.find(link=>link.rel==="alternate");
      if (altLink) url=altLink.href;
    }
    let content=entry.content?.$t || "";
    let img=entry.media$thumbnail?.url || w2_Thumbnail(content);
    img=img.replace(/\/s[0-9]+(-c)?/,"/s480");

    if (i===0){
      mainHTML=`<div class="w2-fancy-main-post"><a href="${url}" aria-label="${title}"><img data-src="${img}" src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 360 220'%3E%3C/svg%3E" alt="${title}" width="360" height="220"/></a><div class="w2-main-post-content"><h3><a href="${url}">${title}</a></h3></div></div>`;
    }else{
      listHTML+=`<div class="w2-fancy-side-post"><a href="${url}" aria-label="${title}"><img data-src="${img}" src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 119 85'%3E%3C/svg%3E" alt="${title}" width="119" height="85"/></a><div class="w2-side-post-content"><h4><a href="${url}">${title}</a></h4></div></div>`;
    }
  }
  const sectionTitleHTML=`<h2 class="w2-section-title">${sectionLabel}</h2>`;
  return `${sectionTitleHTML}<div class="w2-fancy-widget-wrapper">${mainHTML}<div class="w2-fancy-side-list">${listHTML}</div></div>`;
}

(function(){
  var w2Loaded = false;
  async function loadW2Feeds(){
    if(w2Loaded) return;
    w2Loaded = true;

    let fancySections=document.querySelectorAll(".w2-fancy-section-item");
    for (let section of fancySections){
      let container=section.querySelector(".widget-content");
      if (!container) continue;
      let label=container.dataset.label?.trim() || container.textContent?.trim();
      if (!label) continue;
      container.innerHTML=`<div class="w2-loader">جاري تحميل ${label}...</div>`;
      let widgetTitle=section.querySelector(".widget-title")?.textContent || label;
      try{
        const res=await fetch(w2_Feedurl(label,4));
        const data=await res.json();
        const entries=data.feed?.entry || [];
        if (entries.length>0){
          container.innerHTML=w2_PrintFancyFeed(entries,widgetTitle);
        }else{
          container.innerHTML=`<h2 style="text-align:right; margin-bottom:10px; font-size: 20px; color: #333;">${widgetTitle}</h2><p style='text-align:center;'>لا توجد مقالات لعرضها في قسم "${label}".</p>`;
        }
      }catch(error){
        container.innerHTML=`<h2 style="text-align:right; margin-bottom:10px; font-size: 20px; color: #333;">${widgetTitle}</h2><p style='color:red;text-align:center;'>فشل تحميل المقالات</p>`;
      }
    }
    triggerLazyImages();
  }

  window.addEventListener('scroll', loadW2Feeds, {passive: true, once: true});
  window.addEventListener('touchstart', loadW2Feeds, {passive: true, once: true});
  window.addEventListener('mousemove', loadW2Feeds, {passive: true, once: true});
})();

/* ==========================================================
   5. سهم الصعود
   ========================================================== */
const scrollButtonsContainer = document.querySelector(".ba-scroolb");
const progressBar = document.querySelector(".scrolbprogres");
function scrollToTop(){ window.scrollTo({top: 0, behavior: "smooth"}); }
let scrollTicking = false;
function updateScrollEffects(){
  const doc = document.documentElement;
  const scrollTop = doc.scrollTop || window.pageYOffset;
  const scrollHeight = doc.scrollHeight - doc.clientHeight;
  if (scrollButtonsContainer) {
    if (scrollTop > 200) {
      scrollButtonsContainer.classList.add("visible");
    } else {
      scrollButtonsContainer.classList.remove("visible");
    }
  }
  if (progressBar && scrollHeight > 0) {
    const progress = (scrollTop / scrollHeight) * 100;
    const circumference = 2 * Math.PI * 20;
    progressBar.style.strokeDashoffset = circumference - (progress / 100 * circumference);
  }
  scrollTicking = false;
}
function requestScrollTick(){
  if (!scrollTicking) {
    window.requestAnimationFrame(updateScrollEffects);
    scrollTicking = true;
  }
}
window.addEventListener("scroll", requestScrollTick, {passive: true});
window.addEventListener("resize", requestScrollTick, {passive: true});

/* ==========================================================
   6.  تكبير وتصغير النص في المقال
   ========================================================== */
(function() {
  const btnLarge = document.getElementById('large');
  const btnSmall = document.getElementById('small');
  const btnReset = document.getElementById('reset');
  if (!btnLarge || !btnSmall || !btnReset) return;

  const target = document.querySelector('.post-body') || document.body;
  let baseSize = null;
  let currentSize = null;

  function initSize() {
    if (!baseSize) {
      baseSize = parseFloat(window.getComputedStyle(target).fontSize) || 18;
      currentSize = baseSize;
    }
  }

  function updateFontSize(size) {
    currentSize = size;
    const elements = target.querySelectorAll('p, li, span, div, a, h1, h2, h3, h4, h5, h6');
    for (let i = 0; i < elements.length; i++) {
      elements[i].style.fontSize = size + 'px';
      elements[i].style.lineHeight = 'normal';
    }
  }

  btnLarge.addEventListener('click', () => { initSize(); updateFontSize(currentSize + 1); });
  btnSmall.addEventListener('click', () => { initSize(); if (currentSize > 8) updateFontSize(currentSize - 1); });
  btnReset.addEventListener('click', () => { if (baseSize) updateFontSize(baseSize); });
})();

