document.addEventListener("DOMContentLoaded", function() {
  var targetContainer = document.getElementById('contact');
  var contactWidget = document.getElementById('ContactForm1');
  
  if (targetContainer && contactWidget) {
    targetContainer.appendChild(contactWidget);
    contactWidget.style.display = 'block';
  }
});

/* ==========================================================
   9.  كود تسريع وحل مشاكل الوصول وروابط الصفحات 
   ========================================================== */
(function(){
  'use strict';
  
  function fixPagerLinks(){
    var selectors = [
      'a.blog-pager-older-link',
      'a.blog-pager-newer-link',
      'a.home-link',
      '.blog-pager a',
      '.mobile-link-button a',
      '.blog-mobile-link a'
    ];
    
    var allLinks = document.querySelectorAll(selectors.join(','));
    
    for(var i = 0; i < allLinks.length; i++){
      var link = allLinks[i];
      
      var currentText = (link.textContent || '').replace(/\s+/g, ' ').trim();
      var currentAria = link.getAttribute('aria-label') || '';
      
      var newText = '';
      var newAria = '';
      
      if(link.classList.contains('blog-pager-older-link')){
        newText = 'رسائل أقدم';
        newAria = 'الصفحة التالية - رسائل أقدم';
      } 
      else if(link.classList.contains('blog-pager-newer-link')){
        newText = 'رسائل أحدث';
        newAria = 'الصفحة السابقة - رسائل أحدث';
      } 
      else if(link.classList.contains('home-link')){
        newText = 'الرئيسية';
        newAria = 'الصفحة الرئيسية';
      } 
      else {
        var href = link.getAttribute('href') || '';
        if(href.indexOf('updated-max') !== -1){
          newText = 'الصفحة التالية';
          newAria = 'الصفحة التالية';
        } else if(href.indexOf('updated-min') !== -1){
          newText = 'الصفحة السابقة';
          newAria = 'الصفحة السابقة';
        } else {
          newText = 'تصفح';
          newAria = 'تصفح المزيد';
        }
      }
      
      if(!currentAria || currentAria.length < 2){
        link.setAttribute('aria-label', newAria);
        link.setAttribute('title', newAria);
      }
      
      if(currentText.length === 0){
        if(!link.querySelector('.cnq-visually-hidden')){
          var span = document.createElement('span');
          span.className = 'cnq-visually-hidden';
          span.textContent = newText;
          link.appendChild(span);
        }
      }
    }
    
    var w1Links = document.querySelectorAll('.w1-custom-featured-link, .w2-fancy-main-post a, .w2-fancy-side-post a');
    for(var j = 0; j < w1Links.length; j++){
      var w1Link = w1Links[j];
      var w1Text = (w1Link.textContent || '').trim();
      var w1Aria = w1Link.getAttribute('aria-label') || '';
      
      if(w1Text.length === 0 && (!w1Aria || w1Aria.length < 2)){
        var parent = w1Link.closest('.w1-custom-featured-item, .w2-fancy-main-post, .w2-fancy-side-post');
        var title = '';
        if(parent){
          var titleEl = parent.querySelector('h1, h2, h3, h4, h5');
          if(titleEl) title = (titleEl.textContent || '').trim();
        }
        if(!title) title = 'اقرأ المزيد';
        
        w1Link.setAttribute('aria-label', title);
        w1Link.setAttribute('title', title);
        
        if(!w1Link.querySelector('.cnq-visually-hidden')){
          var span = document.createElement('span');
          span.className = 'cnq-visually-hidden';
          span.textContent = title;
          w1Link.appendChild(span);
        }
      }
    }
  }
  
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', fixPagerLinks);
  } else {
    fixPagerLinks();
  }
  
  window.addEventListener('load', function(){
    fixPagerLinks();
    setTimeout(fixPagerLinks, 500);
    setTimeout(fixPagerLinks, 1500);
    setTimeout(fixPagerLinks, 3000);
  });
  
  window.addEventListener('load', function(){
    setTimeout(fixPagerLinks, 1000);
  });

})();

/* ==========================================================
   10.  كود تأخير تحميل الصور 
   ========================================================== */
function triggerLazyImages() {
  var imgs = document.querySelectorAll('img[data-src]');
  for (var i = 0; i < imgs.length; i++) {
    var realSrc = imgs[i].getAttribute('data-src');
    if (realSrc) {
      imgs[i].setAttribute('src', realSrc);
      imgs[i].removeAttribute('data-src');
    }
  }
}

window.addEventListener('scroll', triggerLazyImages, {passive: true, once: true});
window.addEventListener('touchstart', triggerLazyImages, {passive: true, once: true});
window.addEventListener('mousemove', triggerLazyImages, {passive: true, once: true});

/* ==========================================================
   11.   كود تحسين أداء الصور داخل المقال وتسمية الـ Iframe
   ========================================================== */

document.addEventListener("DOMContentLoaded", function() {
    const postBody = document.querySelector('.post-body');
    if (postBody) {
        const postTitle = document.querySelector('.post-title')?.textContent?.trim() || 'صورة توضيحية للمقال';
        const images = postBody.querySelectorAll('img:not([alt])');
        
        images.forEach(img => {
            img.setAttribute('alt', postTitle);
            
            const parentLink = img.closest('a');
            if (parentLink && !parentLink.textContent.trim() && !parentLink.getAttribute('aria-label')) {
                parentLink.setAttribute('aria-label', postTitle);
                parentLink.setAttribute('title', postTitle);
            }
        });
    }

    const commentIframe = document.getElementById('comment-editor');
    if (commentIframe && !commentIframe.getAttribute('title')) {
        commentIframe.setAttribute('title', 'مربع إضافة تعليق');
    }

    const editorSrcLink = document.getElementById('comment-editor-src');
    if (editorSrcLink) {
        editorSrcLink.setAttribute('aria-label', 'مصدر نموذج التعليق');
        editorSrcLink.setAttribute('title', 'مصدر نموذج التعليق');
        
        editorSrcLink.style.position = 'absolute';
        editorSrcLink.style.width = '1px';
        editorSrcLink.style.height = '1px';
        editorSrcLink.style.padding = '0';
        editorSrcLink.style.margin = '-1px';
        editorSrcLink.style.overflow = 'hidden';
        editorSrcLink.style.clip = 'rect(0, 0, 0, 0)';
        editorSrcLink.style.whiteSpace = 'nowrap';
        editorSrcLink.style.border = '0';
    }
});
/* ==========================================================
   12.    كود الحماية والفوتر الخاص بك
   ========================================================== */
(function() {
    'use strict';
    
    const CONFIG = {
        blogId: "7462054215299295136",
        purchaseUrl: "https://www.facebook.com/conquertemplate",
        overlayImg: "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjvgrl39LPYfhno7lwd_7cCO38QFpzscZDANIXNpM5X7zcMUy6DwLlX9ZuZn6wOOmLiRcg4n47IW9eCpwtFQdvYQAUgg4hgAbyFcIWhV5Rf9pOvDQHFCB42iNbvg9FoKiFQeu1i693S46vN2faAk4hcAQD85z5I3itx4OLUVBZx0pQL0RSElUZsoX1l_ggn/s1600/Gemini_Generated_Image_4f4mak4f4mak4f4m.jpg",
        footerLink: "https://conquer-template.blogspot.com/",
        footerImgSrc: "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEg5WSCyFyanpJYHWXcuVPGlvaStE8ke0hm_OT2xzkclY4zesRyHlzaoIR2JUTxDYNKUjV6rlk8Bks4ws6hvey0zYYXeWBseDuvzFRl2x6p3vuwg_ZY-ZHaoVAQzgJsab_thITBlW8WG3VIbWner5QY0dLBvW9QXkAwXG0x65NOpznl8hCft762AVkRqHitW/s36/%D8%AA%D8%B5%D9%85%D9%8A%D9%85%20%D8%A8%D8%AF%D9%88%D9%86%20%D8%B9%D9%86%D9%88%D8%A7%D9%86%20(1).png"
    };

    function lockSite() {
        if (document.documentElement.classList.contains("z9klock")) {
            if (!document.getElementById("theme-license-overlay")) {
                createOverlay();
            }
            return;
        }
        document.documentElement.classList.add("z9klock");
        document.documentElement.classList.remove("z9kjs");
        document.documentElement.style.overflow = "hidden";
        createOverlay();
    }

    function createOverlay() {
        const overlay = document.createElement("a");
        overlay.href = CONFIG.purchaseUrl;
        overlay.target = "_blank";
        overlay.rel = "noopener noreferrer";
        overlay.id = "theme-license-overlay";
        overlay.style.cssText = "position:fixed;top:0;left:0;width:100%;height:100%;background:#f5f5f7;z-index:2147483647;display:flex;align-items:center;justify-content:center;overflow:hidden;cursor:pointer;text-decoration:none;";
        overlay.innerHTML = '<img src="' + CONFIG.overlayImg + '" style="max-width:100vw;max-height:100vh;width:auto;height:auto;display:block;" alt="غير مرخص">';
        document.documentElement.appendChild(overlay);
    }

    function unlockSite() {
        document.documentElement.classList.remove("z9klock");
        document.documentElement.classList.add("z9kjs");
        document.documentElement.style.overflow = "";
        const existingOverlay = document.getElementById("theme-license-overlay");
        if (existingOverlay) {
            existingOverlay.remove();
        }
    }

    const currentUrl = window.location.href.toLowerCase();
    if (currentUrl.includes("post-preview") || currentUrl.includes("www.blogger") || currentUrl.includes("b/layout-preview") || currentUrl.includes("b/preview") || currentUrl.includes("translate.google") || currentUrl.includes("webcache.googleusercontent") || currentUrl.includes("template-editor")) {
        unlockSite();
        return;
    }

    window.z9k_license_callback = function(data) {
        try {
            if (!data || !data.feed || !data.feed.entry || !data.feed.entry.length) {
                lockSite();
                return;
            }
            
            const parser = new DOMParser();
            const doc = parser.parseFromString(data.feed.entry[0].content.$t, 'text/html');
            const listItems = doc.querySelectorAll('li');
            const domains = [];
            
            listItems.forEach(li => {
                const domain = li.textContent.trim().toLowerCase();
                if (domain) domains.push(domain);
            });

            const currentDomain = window.location.hostname.toLowerCase();
            let activated = false;
            
            for (let i = 0; i < domains.length; i++) {
                if (currentDomain === domains[i] || currentDomain.endsWith('.' + domains[i])) {
                    activated = true;
                    break;
                }
            }

            if (activated) {
                unlockSite();
                if (data.feed.entry.length > 1) {
                    const extraDoc = parser.parseFromString(data.feed.entry[1].content.$t, 'text/html');
                    extraDoc.querySelectorAll('style').forEach(s => document.head.appendChild(s));
                    extraDoc.querySelectorAll('script').forEach(s => {
                        const newScript = document.createElement('script');
                        newScript.textContent = s.textContent;
                        document.head.appendChild(newScript);
                    });
                }
                protectFooter();
            } else {
                lockSite();
            }
        } catch (e) {
            console.error("License check error:", e);
            lockSite();
        }
    };

    const script = document.createElement('script');
    script.src = 'https://www.blogger.com/feeds/' + CONFIG.blogId + '/posts/default?alt=json-in-script&callback=z9k_license_callback';
    document.head.appendChild(script);

    function protectFooter() {
        let footer = document.querySelector('.footer-copy');
        if (!footer) {
            footer = document.createElement('div');
            footer.className = 'footer-copy';
            document.body.appendChild(footer);
        }

        let siteTitle = '';
        const metaTitle = document.querySelector('meta[property="og:site_name"]');
        if (metaTitle && metaTitle.content) {
            siteTitle = metaTitle.content.trim();
        } else {
            const headerTitle = document.querySelector('.Header h1, .header h1, #header h1, .header-title');
            if (headerTitle) {
                siteTitle = headerTitle.textContent.trim();
            } else {
                const parts = document.title.split(/[:\-\|]/);
                siteTitle = parts[parts.length - 1].trim();
            }
        }

        const currentYear = new Date().getFullYear();
        const homeUrl = window.location.origin;

        footer.innerHTML = `
            <a href="${CONFIG.footerLink}" target="_blank" rel="noopener noreferrer" style="display:inline-block;vertical-align:middle;margin-inline-end:6px;">
                <img src="${CONFIG.footerImgSrc}" width="24" height="24" alt="حقوق القالب" style="vertical-align:middle;display:inline-block;">
            </a>
            <span>جميع الحقوق محفوظة &#169; ${currentYear} - </span>
            <a class="site-title-link" href="${homeUrl}" style="color:inherit;text-decoration:none;font-weight:bold;">
                <span class="site-title">${siteTitle || 'مدونتي'}</span>
            </a>
        `;

        const observer = new MutationObserver(function() {
            const link = footer.querySelector('a[href="' + CONFIG.footerLink + '"]');
            if (!link) {
                lockSite();
                return;
            }
            const img = link.querySelector('img');
            if (!img || window.getComputedStyle(img).display === 'none' || window.getComputedStyle(img).opacity === '0' || window.getComputedStyle(img).visibility === 'hidden' || img.offsetWidth === 0) {
                lockSite();
            }
        });
        
        observer.observe(footer, { childList: true, subtree: true, attributes: true });
    }

})();
